section.p:
        NOTE: These two methods are available in SPanel and should be implemented in subclasses: 

/** 
 * Used by Scope to set the window frame title. 
 */ 
public String getTitle(){ 
    return "Login"; 
} 
/** 
 * 
 * Used by Scope to end the application when the window is closed 
 */ 
public Control getCloseControl() { 
    return new Control(LoginController.EXIT_CONTROL_ID); 
}
